terminalCaptures.command:
{
kubectl get pvc,ingress,hpa -n taskboard
helm list -n taskboard
kubectl get application labboard -n argocd
}

{
terraform -chdir=terraform init -backend=false -input=false
terraform -chdir=terraform fmt -check
terraform -chdir=terraform validate
}

{
aws ec2 describe-vpcs --region ap-south-1 --vpc-ids vpc-0c7cf8e38424738a7 --query 'Vpcs[].{Vpc:VpcId,State:State,CIDR:CidrBlock}' --output table
aws eks describe-cluster --region ap-south-1 --name session21-labboard --query 'cluster.{Name:name,Version:version,Status:status}' --output table
aws eks describe-nodegroup --region ap-south-1 --cluster-name session21-labboard --nodegroup-name lab-20261016162203994500000015 --query 'nodegroup.{Status:status,InstanceTypes:instanceTypes,Desired:scalingConfig.desiredSize,Health:health.issues}' --output json
kubectl --kubeconfig /tmp/labboard-foot-20261016/eks-kubeconfig get nodes
}

{
aws ec2 describe-subnets --region ap-south-1 --filters Name=vpc-id,Values=vpc-0c7cf8e38424738a7 --query 'Subnets[].{Subnet:SubnetId,Zone:AvailabilityZone,PublicIP:MapPublicIpOnLaunch}' --output table
aws ec2 describe-instances --region ap-south-1 --instance-ids i-050b60ab4f9df119a --query 'Reservations[].Instances[].{Instance:InstanceId,Type:InstanceType,State:State.Name,Subnet:SubnetId}' --output table
aws ecr describe-repositories --region ap-south-1 --query 'repositories[?starts_with(repositoryName, `session21-labboard`)].{Name:repositoryName,Tags:imageTagMutability,URI:repositoryUri}' --output table
}

{
kubectl exec -n taskboard deployment/taskboard-taskboard-backend -c backend -- python -c 'from urllib.request import urlopen; print(urlopen("http://localhost:8000/metrics").read().decode())' | rg "^(http_requests_total|process_resident_memory_bytes|process_cpu_seconds_total|http_request_duration_seconds_count)"
}
